# Try nearest symbol for the unresolved SGen worker frames
aarch64-linux-gnu-nm -C /tmp/libmonosgen-2.0.so.dbg 2>/dev/null | sort | awk -v addr1="0x2f4b20" -v addr2="0x2f4c84" '
{
  a = strtonum("0x"$1)
  if (a <= strtonum(addr1)) { sym1 = $3; off1 = strtonum(addr1) - a }
  if (a <= strtonum(addr2)) { sym2 = $3; off2 = strtonum(addr2) - a }
}
END {
  printf "#02 pc 0x2f4b20: %s+0x%x\n", sym1, off1
