arguments.command:
# Let's check if there's actual code there or if these are in a data section
aarch64-linux-gnu-readelf -S /tmp/libmonosgen-2.0.so.dbg | grep -E "\.text|\.bss|\.data" | head -10
echo "---"
# Check what section 0x2f4b20 falls in
aarch64-linux-gnu-readelf -S /tmp/libmonosgen-2.0.so.dbg | awk 'NR>5{
  if ($2 ~ /^\./) {
    name=$2; addr=strtonum("0x"$4); size=strtonum("0x"$6)
    if (0x2f4b20 >= addr && 0x2f4b20 < addr+size) print "0x2f4b20 is in section:", name, "addr:", $4, "size:", $6
  }
}'

